/**
 * A single-word Term on one Field, and on another a multi-word Term beside the
 * Symbol Rule from #4, so a Field can be read violating both kinds of Rule.
 */
const rules = [
  term({
    field: 'name',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
