        text: 'utilise',
        offset: 11,
      },
    ])
  })

  it('produces no Violation where the Term sits inside a longer word', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client utilises the open SSID.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('produces no Violation where a hyphen or underscore carries the Term into a longer word', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client will re-utilise the open_utilise_profile.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('produces a Violation where the Term closes the Field', async () => {
