    })

    expect(response.json().violations).toEqual([
      expect.objectContaining({ field: 'summary', rule: 'no-utilise', offset: 16 }),
    ])
  })

  it('produces a Violation carrying the whole phrase where the Term is more than one word', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client joins the wireless network.',
    })

    expect(response.json().violations).toEqual([
      {
        field: 'summary',
        rule: 'no-wireless-network',
        reason: 'The product documentation says WLAN, not wireless network.',
        text: 'wireless network',
        offset: 21,
      },
    ])
  })

  it('produces a Violation where a line break falls inside the phrase', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client joins the wireless\nnetwork.',
    })

    expect(response.json().violations).toEqual([
      expect.objectContaining({ rule: 'no-wireless-network', offset: 21 }),
