  it('leaves a Test Case producing a Violation unwritten', async () => {
    const { testlink } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client utilise the open SSID.',
    })

    expect(testlink.written).toEqual([])
  })

  it('carries the same Field, rule id, reason, matched text and offset a Symbol Violation does', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client utilise the open SSID.',
    })

    const [violation] = response.json().violations
    expect(Object.keys(violation)).toEqual(['field', 'rule', 'reason', 'text', 'offset'])
  })
})

describe('a Field violating a Term Rule and a Symbol Rule', () => {
