/**
 * Whether an operator has applied `schema.sql` to this database. Asked outright
 * rather than read out of the error a missing table would raise: absence is told
 * from unreachability by what the database says about itself, never by matching
 * the text of a failure.
 */
async function hasSchema(queries: Queries): Promise<boolean> {
  const rows = await queries.run(
    "select 1 from information_schema.tables where table_name = 'rules'",
  )

  return rows.length > 0
}

/**
 * The enabled Exceptions, gathered under the Rule each belongs to. Read in a
 * statement of its own rather than joined: a Rule with no Exception is the
 * common one, and a join would answer for it with a row of nulls to tell apart
 * from a row carrying a phrase.
 */
async function exceptionsByRule(queries: Queries): Promise<Map<number, string[]>> {
  const rows = await queries.run(
    'select rule, phrase from rule_exceptions where enabled order by id',
  )
  const byRule = new Map<number, string[]>()

  for (const row of rows) {
    const rule = Number(row.rule)
    const phrases = byRule.get(rule)

    if (phrases === undefined) {
      byRule.set(rule, [String(row.phrase)])
      continue
    }

    phrases.push(String(row.phrase))
  }

  return byRule
}

import { Client } from '@modelcontextprotocol/sdk/client/index.js'
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js'

import type { ToolCaller, ToolResult } from './tool-caller.js'

/**
 * Speaks to a testlink-mcp process over stdio. testlink-mcp answers in text
 * whether a call worked or not, so all this does is put that text and the one
 * structural signal beside it in reach of the client above — every reading of
 * what TestLink said happens there, where it can be exercised without a process.
 */
export async function connectToTestLinkMcp(server: {
  command: string
  args: string[]
  env: Record<string, string>
}): Promise<ToolCaller> {
  const client = new Client({ name: 'testcase-validator', version: '0.0.0' })

  await client.connect(new StdioClientTransport(server))

  return {
    async call(tool: string, args: Record<string, unknown>): Promise<ToolResult> {
      const result = await client.callTool({ name: tool, arguments: args })

      return { text: textOf(result.content), isError: result.isError === true }
    },
  }
}

/** What testlink-mcp said, which it says as text and nothing else. */
function textOf(content: unknown): string {
  if (!Array.isArray(content)) {
    return ''
  }

  return content
    .filter((part): part is { type: 'text'; text: string } => part?.type === 'text')
    .map((part) => part.text)
    .join('')
}

