 * everything finer is read out of the text by the client above.
 */
export interface ToolResult {
  text: string
  isError: boolean
}

/**
 * The path to testlink-mcp, one tool call at a time. Narrow on purpose: it is
 * the seam that lets the real TestLink client be exercised — the tools it
 * calls, the arguments it sends, and how it reads what comes back — without a
 * TestLink instance or a spawned process.
 */
export interface ToolCaller {
  call(tool: string, args: Record<string, unknown>): Promise<ToolResult>
}

